期(10〜12月)", "required": true}, {"key": "education*term4", "label": "4期(1〜3月)", "required": true}], "hint": "年齢に応じ、子どもを主語に(0歳=3視点/1歳〜=5領域)。"}, {"key": "aid", "label": "保育者の援助", "fields": [{"key": "aid*term1", "label": "1期(4〜6月)", "required": true, "examples": ["一人ひとりの思いを受け止め、安心して過ごせるよう関わる。"]}, {"key": "aid*term2", "label": "2期(7〜9月)", "required": true}, {"key": "aid*term3", "label": "3期(10〜12月)", "required": true}, {"key": "aid*term4", "label": "4期(1〜3月)", "required": true}], "hint": "保育者を主語に。子どもの育ちを支える関わりを。"}, {"key": "withhome", "label": "子育ての支援", "fields": [{"key": "withhome*term1", "label": "1期(4〜6月)", "required": true, "examples": ["連絡帳や送迎時の会話で子どもの様子を共有し、安心につなげる。"]}, {"key": "withhome*term2", "label": "2期(7〜9月)", "required": true}, {"key": "withhome*term3", "label": "3期(10〜12月)", "required": true}, {"key": "withhome*term4", "label": "4期(1〜3月)", "required": true}], "hint": "保護者を主語に含め、家庭との連携・支援を。"}, {"key": "schedule", "label": "園行事及び園事業", "fields": [{"key": "schedule*term1", "label": "1期(4〜6月)", "required": false}, {"key": "schedule*term2", "label": "2期(7〜9月)", "required": false}, {"key": "schedule*term3", "label": "3期(10〜12月)", "required": false}, {"key": "schedule*term4", "label": "4期(1〜3月)", "required": false}]}]'::jsonb, false)
on conflict (plan_type, coalesce(age_variant,''), version) do update set title=excluded.title, sections=excluded.sections;

